                Rigidbody2D body=a.identity.torso.Rigidbody;if(!enableM1&&a.curriculum.mode==NativeTrialMode.Settling)StartCurriculumTrial(a);a.identity.torso.FillNativeGlobalInputs(a.globalInputs);PrepareM1Output(a);var proprio=new NativeLocalProprioception{worldPosition=body.position,worldRotationDegrees=body.rotation,localLinearVelocity=Quaternion.Euler(0f,0f,-body.rotation)*body.linearVelocity};NativeObservation current=a.model.Observe(a.globalInputs,a.limbs,Tick,proprio,enableM1,a.m1Output,a.practiceActive,a.identity.creatureId,a.bodySignature,SampleTerrain(body));current.episode=a.trialEpisode;PushHistory(a,current);Vector2 command=MovementCommand(a,current);NativeMovementObservation next=BuildMovementObservation(a,current,command,body);
