    private static bool ContactChanged(NativeMovementObservation a,NativeMovementObservation b){NativeObservation x=a?.history?.LastOrDefault(o=>o!=null),y=b?.history?.LastOrDefault(o=>o!=null);if(x?.jointFeatures==null||y?.jointFeatures==null)return false;for(int l=0;l<Mathf.Min(a.limbCount,b.limbCount);l++)for(int k=4;k<=6;k++){int i=l*NativeCreatureModel.JointFeatureSize+k;if((x.jointFeatures[i]>.5f)!=(y.jointFeatures[i]>.5f))return true;}return false;}
    private static void PushHistory(NativeAgent a,NativeObservation current){a.movementHistory.Enqueue(NativeReplayBuffer.CloneObservation(current));while(a.movementHistory.Count>NativeMovementWeights.HistoryLength)a.movementHistory.Dequeue();}
    private static NativeMovementObservation BuildMovementObservation(NativeAgent a,NativeObservation current,Vector2 command,Rigidbody2D body){NativeObservation[] frames=a.movementHistory.ToArray();var history=new NativeObservation[NativeMovementWeights.HistoryLength];NativeObservation fallback=frames.Length==0?current:frames[0];for(int i=0;i<history.Length;i++){int source=frames.Length-history.Length+i;history[i]=NativeReplayBuffer.CloneObservation(source>=0?frames[source]:fallback);}Vector2 gravity=Quaternion.Euler(0f,0f,-body.rotation)*Physics2D.gravity.normalized;return new NativeMovementObservation{history=history,oscillatorSin=Mathf.Sin(a.oscillatorPhase),oscillatorCos=Mathf.Cos(a.oscillatorPhase),angularVelocity=body.angularVelocity,rhythmTicksRemaining=Mathf.Max(0,a.nextRhythmTick-current.tick),heldRhythm=(float[])a.heldRhythm.Clone(),limbCount=current.limbCount,episode=a.trialEpisode,tick=current.tick,controllerId=a.identity.creatureId,bodySignature=a.bodySignature,command=command,gravityLocal=gravity};}
    private static Vector2 MovementCommand(NativeAgent a,NativeObservation current){if(!a.evaluationEpisode&&a.curriculum!=null&&a.curriculum.IsPractice&&a.trialEpisode%3==0)return Vector2.zero;return current.goal.sqrMagnitude>1e-6f?current.goal.normalized:Vector2.right;}
    private static void ClearMovementControl(NativeAgent a){if(a==null)return;a.movementObservation=null;a.movementDecision=null;a.movementHistory.Clear();}

    private void PromoteSchoolBodiesWhenReady()
    {
        if(schoolBodiesExpanded||enableM1||agents.Count<4||!agents.All(a=>a.curriculum!=null&&a.curriculum.passedStages.Any(s=>s>=7)))return;schoolBodiesExpanded=true;movementLearner?.MarkSimpleBodyQualified();foreach(NativeAgent victim in agents.OrderBy(a=>a.reservedSlot).Skip(2).ToArray()){int slot=victim.reservedSlot;Spawn(CreateSeedBody(slot),"school_transfer_"+slot,"m1_seed_"+slot,seedPolicy.Clone(),slot,0,rtNeat.Seed());RemoveAgentObject(victim);}Status="Movement school transfer: two simple-body collectors and two morphology collectors";
    }

    private void AccumulateIntervalContacts()
    {
        foreach(NativeAgent a in agents) if(a.sequenceActive) for(int i=0;i<a.limbs.Length&&i<NativeCreatureModel.MaxLimbs;i++){Limb limb=a.limbs[i];if(limb==null)continue;a.intervalEnvironmentContact[i]|=limb.TouchingEnvironment;a.intervalSelfContact[i]|=limb.TouchingSelf;a.intervalOtherContact[i]|=limb.TouchingOtherCreature;}
    }

    private void AdvanceOpenSequences()
    {
        SequenceStep=0;
        foreach(NativeAgent a in agents)
        {
            if(!a.sequenceActive||a.brain==null||a.brain.IsDead||a.identity?.torso==null)continue;int elapsed=Tick-a.sequenceStartTick;if(elapsed<=0||elapsed%NativeCreatureModel.ActionTicks!=0)continue;int reached=elapsed/NativeCreatureModel.ActionTicks-1;if(reached<0||reached>=NativeCreatureModel.PlanningHorizon)continue;
            RecordM3Targets(a,reached,out Vector2 worldDelta,out Vector2 local,out Vector2 heading);LastActualPositions[reached]=local;LastActualHeadings[reached]=heading;a.model.RecordMeasuredProgress(worldDelta);SequenceStep=reached+1;
            int next=reached+1;if(next<NativeCreatureModel.PlanningHorizon)ApplySequenceAction(a,next);else a.sequenceActive=false;
        }
    }

