        for(int i=0;i<NativeSpawnSlots;i++){GameObject lane=new GameObject("NativeTrainingLane_"+i);lane.transform.SetParent(trainingLaneRoot.transform);lane.transform.position=LaneCenter(i);var renderer=lane.AddComponent<SpriteRenderer>();renderer.sprite=BodyUtils.GetSquareSprite();renderer.color=new Color(.28f,.22f,.16f);lane.transform.localScale=new Vector3(TrainingLaneMaximumLength,TrainingLaneThickness,1f);BoxCollider2D collider=lane.AddComponent<BoxCollider2D>();collider.size=Vector2.one;collider.sharedMaterial=NativePhysicsMaterials.Ground;lane.AddComponent<GroundSurface>();}
    }
    private void EndTrainingArena(){if(trainingLaneRoot!=null)trainingLaneRoot.SetActive(false);if(ecosystemGround==null)ecosystemGround=GameObject.Find("Ground");if(ecosystemGround!=null)ecosystemGround.SetActive(true);}
    private static Vector2 LaneCenter(int slot)=>new Vector2((Mathf.Abs(slot)%NativeSpawnSlots-(NativeSpawnSlots-1)*.5f)*TrainingLaneSpacing,WorldLayout.GroundTop);
    private static Vector2 LaneTangent(float degrees)=>new Vector2(Mathf.Cos(degrees*Mathf.Deg2Rad),Mathf.Sin(degrees*Mathf.Deg2Rad));
    private static Vector2 LaneNormal(float degrees)=>new Vector2(-Mathf.Sin(degrees*Mathf.Deg2Rad),Mathf.Cos(degrees*Mathf.Deg2Rad));
    // The collider transform is the source of truth.  Keeping both endpoints in this
    // local frame prevents a rotated/moved island from reversing a curriculum trial.
    public static void CurriculumEndpointsForTesting(Vector2 islandCenter,float islandRotation,float islandLength,int direction,float distance,float clearance,out Vector2 spawn,out Vector2 goal)
    {
        Vector2 axis=LaneTangent(islandRotation),normal=LaneNormal(islandRotation);float usableHalf=Mathf.Max(0f,islandLength*.5f-TrainingLaneEdgeInset);Vector2 groundOffset=normal*(TrainingLaneThickness*.5f+Mathf.Max(0f,clearance));spawn=islandCenter-axis*(Mathf.Sign(direction)*usableHalf)+groundOffset;goal=spawn+axis*(Mathf.Sign(direction)*distance);
    }
    private static void CurriculumEndpoints(Transform island,int direction,float distance,float clearance,out Vector2 spawn,out Vector2 goal)
    {
        CurriculumEndpointsForTesting(island.position,island.eulerAngles.z,island.lossyScale.x,direction,distance,clearance,out spawn,out goal);
    }
    private void StartCurriculumTrial(NativeAgent a)
    {
        EnsureTrainingArena();if(a.curriculum==null)a.curriculum=new NativeCurriculumState();if(a.curriculum.mode==NativeTrialMode.Settling)NativeSuccessCurriculum.StartNextTrial(a.curriculum);NativeDeterministicRng trialRandom=new NativeDeterministicRng(a.curriculum.randomState==0?(ulong)(7101+a.reservedSlot):a.curriculum.randomState);int stage=NativeSuccessCurriculum.TrialStage(a.curriculum,ref trialRandom);a.curriculum.randomState=trialRandom.State;float perturb=a.curriculum.IsPractice?(trialRandom.NextFloat()*2f-1f):0f;float milestoneDistance=NativeSuccessCurriculum.Distance(stage)*(a.curriculum.IsPractice ? (.9f+trialRandom.NextFloat()*.2f) : 1f);float slope=NativeSuccessCurriculum.SlopeDegrees(stage)+perturb;int direction=NativeSuccessCurriculum.Direction(stage);float signedSlope=direction>0?slope:-slope;GameObject lane=trainingLaneRoot.transform.GetChild(a.reservedSlot).gameObject;lane.SetActive(true);lane.transform.position=LaneCenter(a.reservedSlot);lane.transform.rotation=Quaternion.Euler(0f,0f,signedSlope);lane.transform.localScale=new Vector3(TrainingLaneMaximumLength,TrainingLaneThickness,1f);Vector2 normal=lane.transform.up,heading=(Vector2)lane.transform.right*direction;CurriculumEndpoints(lane.transform,direction,TrainingLaneMaximumLength-2f*TrainingLaneEdgeInset,BodyClearance(a,normal,signedSlope),out Vector2 start,out Vector2 goal);a.lane=lane;a.trialStage=stage;a.trialDistance=milestoneDistance;a.trialLaneHalfLength=TrainingLaneMaximumLength*.5f;a.trialDirection=heading;a.trialNormal=normal;a.trialStart=start;a.trialGoal=goal;a.trialStartedTick=Tick;a.trialEpisode++;a.evaluationEpisode=a.trialEpisode%5==0;ResetTrialBody(a,a.trialStart,signedSlope);a.sustainedTrial.Reset(0f,BodyMorphologyRules.TorsoWidth);a.model.SetCurriculumGoal(a.trialGoal,heading,Tick+Mathf.RoundToInt(TrainingTimeoutSeconds/Time.fixedDeltaTime));Status=$"Curriculum {NativeSuccessCurriculum.Label(stage)} {a.curriculum.mode}: { (direction>0?"left spawn -> right goal":"right spawn