    }
    private void ResetTrialBody(NativeAgent a,Vector2 torsoPosition,float torsoRotation)
    {
        if(a.resetPose==null||a.resetPose.Count==0)CaptureResetPose(a);foreach(NativeBodyResetPose pose in a.resetPose){if(pose.body==null)continue;pose.body.position=torsoPosition+(Vector2)(Quaternion.Euler(0f,0f,torsoRotation)*pose.localOffset);pose.body.rotation=torsoRotation+pose.rotationOffset;pose.body.linearVelocity=Vector2.zero;pose.body.angularVelocity=0f;pose.body.Sleep();}a.brain.ExpireActions();a.model.ResetOscillatorPhase();Physics2D.SyncTransforms();foreach(NativeBodyResetPose pose in a.resetPose)pose.body?.WakeUp();a.sequenceActive=false;a.observation=null;a.sequence=null;if(a.curriculum.mode!=NativeTrialMode.Qualification&&a.curriculum.mode!=NativeTrialMode.Retention){a.evaluationWeights=null;a.evaluationOptimizer=null;}a.trialSettlingTicks=0;a.motionWindowTicks=a.movingEvidenceTicks=a.stillEvidenceTicks=0;a.isSustainedMoving=false;a.oscillatorPhase=0f;a.nextRhythmTick=Tick;Array.Clear(a.heldRhythm,0,a.heldRhythm.Length);ClearMovementControl(a);
