    }
    private void ResetToEcosystemSpawn(NativeAgent a){Vector2 target=NativeSpawnPosition(a.reservedSlot);ResetTrialBody(a,target,0f);}
    private float[] SampleTerrain(Rigidbody2D body)
    {
        float[] values=new float[12];Vector2 right=body.transform.right,origin=body.position;for(int i=0;i<3;i++){RaycastHit2D hit=Physics2D.Raycast(origin+right*(i-1),Vector2.down,8f);int o=i*4;if(hit.collider==null)continue;Vector2 local=Quaternion.Euler(0f,0f,-body.rotation)*hit.normal;values[o]=1f;values[o+1]=hit.distance/8f;values[o+2]=local.x;values[o+3]=local.y;}return values;
    }
    private void UpdateCurriculumTrials()
    {
        EnsureTrainingArena();int completed=0;var lines=new List<string>();foreach(NativeAgent a in agents)
        {
            if(a.brain==null||a.identity?.torso==null||a.curriculum==null)continue;if(a.curriculum.Complete)completed++;
            Rigidbody2D body=a.identity.torso.Rigidbody;Vector2 relative=body.position-a.trialStart;float progress=Vector2.Dot(relative,a.trialDirection);float lateral=Mathf.Abs(Vector2.Dot(relative,a.trialNormal));bool support=a.identity.torso.TouchingGround||a.limbs.Any(l=>l!=null&&l.TouchingEnvironment);
            if(a.trialSettlingTicks<10){a.trialSettlingTicks=support&&body.linearVelocity.sqrMagnitude<=.01f&&Mathf.Abs(body.angularVelocity)<=5f?a.trialSettlingTicks+1:0;if(Tick-a.trialStartedTick>=Mathf.RoundToInt(10f/Time.fixedDeltaTime)){GoalFailures++;NativeSuccessCurriculum.RegisterFailure(a.curriculum,a.model.Weights);Status="Settling timeout: "+NativeSuccessCurriculum.Label(a.trialStage);StartCurriculumTrial(a);continue;}if(a.trialSettlingTicks<10){lines.Add($"{a.reservedSlot}:{NativeSuccessCurriculum.Label(a.trialStage)} settling {a.trialSettlingTicks}/10");continue;}a.trialStartedTick=Tick;}
            Vector2 islandOffset=body.position-(Vector2)a.lane.transform.position;float islandAlong=Mathf.Abs(Vector2.Dot(islandOffset,a.trialDirection)),islandLateral=Mathf.Abs(Vector2.Dot(islandOffset,a.trialNormal));float tolerance=NativeSuccessCurriculum.GoalTolerance(a.trialStage);bool sustainedEvaluation=a.curriculum.mode==NativeTrialMode.Qualification||a.curriculum.mode==NativeTrialMode.Retention;if(sustainedEvaluation)a.sustainedTrial.Observe(progress,Time.fixedDeltaTime);bool timedOut=Tick-a.trialStartedTick>=Mathf.RoundToInt(TrainingTimeoutSeconds/Time.fixedDeltaTime),leftLane=islandAlong>a.trialLaneHalfLength||islandLateral>TrainingLaneThickness*.5f+5f;bool success=sustainedEvaluation?timedOut&&!leftLane&&a.sustainedTrial.Qualified(Time.fixedDeltaTime):support&&progress>=a.trialDistance-tolerance;bool failed=sustainedEvaluation?(leftLane||timedOut&&!success):(timedOut||leftLane);
            if(success||failed)
            {
                NativeTrialMode prior=a.curriculum.mode;
                if(success){GoalSuccesses++;NativeSuccessCurriculum.RegisterSuccess(a.curriculum,a.model.Weights);if(prior==NativeTrialMode.Training&&a.curriculum.mode==NativeTrialMode.Qualification){a.curriculum.qualificationLearningState=a.model.Capture();a.curriculum.qualificationLearningState.weights=a.curriculum.qualificationSnapshot.Clone();}if(prior==NativeTrialMode.Qualification&&a.curriculum.mode!=NativeTrialMode.Qualification&&a.curriculum.validatedSnapshot!=null){a.curriculum.validatedLearningState=a.curriculum.qualificationLearningState?.Clone();movementLearner?.SaveQualifiedSnapshot(a.evaluationWeights,a.evaluationOptimizer);}Status="Goal success: "+NativeSuccessCurriculum.Label(a.trialStage);}
                else{GoalFailures++;NativeSuccessCurriculum.RegisterFailure(a.curriculum,a.model.Weights);Status="Goal retry: "+NativeSuccessCurriculum.Label(a.trialStage);}
                bool repeatRetention=prior==NativeTrialMode.Retention&&!success&&!a.curriculum.retentionUsingSnapshot&&a.curriculum.validatedSnapshot!=null;
                if(repeatRetention){a.curriculum.retentionUsingSnapshot=true;a.evaluationWeights=null;a.evaluationOptimizer=null;Status="Retention comparison: frozen snapshot";}
                else
                {
                    if(prior==NativeTrialMode.Retention&&!success&&a.curriculum.retentionUsingSnapshot){NativeSuccessCurriculum.FlagRegression(a.curriculum);movementLearner?.RollbackToQualified();Status="Retention regression: restored qualified movement snapshot";}
                    a.curriculum.retentionUsingSnapshot=false;a.curriculum.retentionStage=-1;
                    if(a.curriculum.mode!=NativeTrialMode.Qualification)a.curriculum.mode=NativeTrialMode.Settling;
                }
