    public static bool IsTemporaryGoalReached(Vector2 position,Vector2 goal)=>(position-goal).sqrMagnitude<=TemporaryGoalReachRadius*TemporaryGoalReachRadius;
    private void UpdateTemporaryGoalRewards(){if(enableM1)return;int block=Mathf.Max(0,Tick)/NativeCreatureModel.GoalWindowTicks;foreach(NativeAgent a in agents){if(a.temporaryGoalRewardBlock==block||a.observation==null||a.identity?.torso==null||a.brain==null||a.brain.IsDead)continue;if(!IsTemporaryGoalReached(a.identity.torso.Rigidbody.position,a.model.CurrentWorldGoal))continue;a.identity.torso.AddEnergy(TemporaryGoalRewardEnergy);a.temporaryGoalRewardBlock=block;Status="Temporary goal reached: +"+TemporaryGoalRewardEnergy.ToString("F0")+" energy";}}
    private void UpdateEnergyBarDisplays(){foreach(NativeAgent a in agents)if(a.energyBar!=null&&a.identity?.torso!=null)a.energyBar.Refresh(Tick);}
    private void UpdateMotionEvidence(){foreach(NativeAgent a in agents){if(a.brain==null||a.brain.IsDead||a.identity?.torso?.Rigidbody==null||!a.ReadyForLearning){a.movingEvidenceTicks=a.stillEvidenceTicks=a.motionWindowTicks=0;a.isSustainedMoving=false;continue;}if(a.motionWindowTicks<=0)a.motionWindowStartPosition=a.identity.torso.Rigidbody.position;a.motionWindowTicks++;if(a.motionWindowTicks<10)continue;float speed=(a.identity.torso.Rigidbody.position-a.motionWindowStartPosition).magnitude/Mathf.Max(.0001f,a.motionWindowTicks*Time.fixedDeltaTime);a.motionWindowStartPosition=a.identity.torso.Rigidbody.position;a.motionWindowTicks=0;if(a.isSustainedMoving){a.stillEvidenceTicks=speed<=.025f?a.stillEvidenceTicks+1:0;if(a.stillEvidenceTicks>=2)a.isSustainedMoving=false;}else{a.movingEvidenceTicks=speed>=.08f?a.movingEvidenceTicks+1:0;if(a.movingEvidenceTicks>=2)a.isSustainedMoving=true;}}}
    private void LateUpdate(){if(PopulationDynamicsEnabled)MaintainPopulationInvariant();foreach(NativeAgent a in agents.ToArray()){if(a.identity?.torso==null||a.brain==null)continue;float energy=a.identity.torso.energy;if(!a.practiceActive)a.m1EnergyFitness+=energy-a.previousEnergy;a.previousEnergy=energy;if(a.m1Genome!=null)a.m1Genome.fitness=a.m1EnergyFitness-a.deathPenalty;if(a.brain.IsDead&&!a.deathRecorded){RecordDeathPenalty(a);}}if(Time.time>=nextCheckpoint){nextCheckpoint+=checkpointIntervalSeconds;SaveCheckpoint();}}
    private void HandleControlFailure(NativeAgent a,Exception e){ControlFailures++;LastControlError=a.identity==null?e.Message:a.identity.creatureId+": "+e.Message;Debug.LogError("Native control failed for creature "+LastControlError+"\n"+e);if(a.brain!=null&&!a.brain.IsDead)a.brain.Kill("native_control_error");}
    private void SeedPopulation(){bool qualified=movementLearner?.Capture().simpleBodyQualified??false;for(int i=agents.Count;i<Mathf.Clamp(populationTarget,1,NativeSpawnSlots);i++){BodyGenomeDto body=qualified&&i>=2?CreateSeedBody(i):CreateMovementSchoolBody();Spawn(body,qualified&&i>=2?"school_transfer_"+i:"movement_school_simple","m1_seed_"+(i%InitialBodySpeciesCount),seedPolicy.Clone(),i,0,rtNeat.Seed());}}
    private void MaintainPopulationInvariant(){if(!PopulationDynamicsEnabled)return;populationTarget=Mathf.Clamp(populationTarget,1,NativeSpawnSlots);if(agents.Count<populationTarget)SeedPopulation();}
    private void ReplaceDeadCreaturesImmediately(){if(!PopulationDynamicsEnabled)return;bool changed=false;foreach(NativeAgent victim in agents.Where(a=>a.brain==null||a.brain.IsDead).ToArray()){if(!agents.Contains(victim))continue;RecordDeathPenalty(victim);try{NativeAgent parent=SelectLivingParent();if(parent==null)RespawnSameGenotype(victim,victim.reservedSlot);else ReplaceAgent(victim,parent,victim.reservedSlot);replacementRetries.Remove(victim);ReplacementRetryState="none";ImmediateReplacementCount++;LastReplacementTick=Tick;changed=true;}catch(Exception e){int retries=replacementRetries.TryGetValue(victim,out int prior)?prior:0;if(retries==0){replacementRetries[victim]=1;ReplacementRetryState="queued retry for slot "+victim.reservedSlot;Debug.LogError("Native replacement failed once; retry queued: "+e.Message);}else{replacementRetries.Remove(victim);ReplacementRetryState="retry failed for slot "+victim.reservedSlot;}}}if(changed)RebuildSpeciation();}
    private NativeAgent SelectLivingParent(){Dictionary<string,float> fitness=NativeNestedSpeciation.SharedFitness(species);NativeAgent[] eligible=agents.Where(a=>a.brain!=null&&!a.brain.IsDead&&NativeCreatureModel.IsFinite(a.model.BodyFitness)&&!a.protectedOffspring).ToArray();if(eligible.Length==0)return null;NativeAgent best=null;float quality=float.NegativeInfinity;for(int i=0;i<3;i++){NativeAgent c=eligible[random.Next(eligible.Length)];float q=fitness.TryGetValue(c.identity.creatureId,out float value)?value:0f;if(q>quality){best=c;quality=q;}}return best;}
    private void RespawnSameGenotype(NativeAgent victim,int slot){BodyGenomeDto body=JsonConvert.DeserializeObject<BodyGenomeDto>(JsonConvert.SerializeObject(victim.body));NativeCreatureSave save=victim.model.Capture();Spawn(body,victim.identity.speciesId,victim.brain.M1SpeciesId,save.weights,slot,victim.bodyAgeGenerations,victim.m1Genome.Copy(),save,learner?.Capture(victim.identity.creatureId)??victim.m3);RemoveAgentObject(victim);}
    private void ReplaceAgent(NativeAgent victim,NativeAgent parent,int slot)
    {
        BodyGenomeDto child=JsonConvert.DeserializeObject<BodyGenomeDto>(JsonConvert.SerializeObject(parent.body));int age=parent.bodyAgeGenerations+1;bool changed=bodyMutationCooldownGenerations<=0||age>=bodyMutationCooldownGenerations;if(changed){MutateBody(child);age=0;}NativeAgent m1Parent=agents.Where(a=>a.brain!=null&&!a.brain.IsDead&&a.identity.speciesId==parent.identity.speciesId).OrderByDescending(a=>a.m1EnergyFitness).FirstOrDefault()??parent;NativeAgent mate=agents.Where(a=>a!=m1Parent&&a.m1Genome!=null&&a.m1Genome.species==m1Parent.m1Genome.species).OrderByDescending(a=>a.m1EnergyFitness).FirstOrDefault()??m1Parent;RtNeatGoalGenome genome=enableM1?rtNeat.Breed(m1Parent.m1Genome,mate.m1Genome):m1Parent.m1Genome.Copy();NativeCreatureSave save=parent.model.Capture();NativeM3LearningState m3=changed?null:(learner?.Capture(parent.identity.creatureId)??parent.m3);Spawn(child,parent.identity.speciesId,"rtneat_"+genome.species,save.weights,slot,age,genome,save,m3);agents[agents.Count-1].protectedOffspring=changed;RemoveAgentObject(victim);Generation++;
    }
    private void RemoveAgentObject(NativeAgent victim){if(victim.identity!=null){modelsById.TryRemove(victim.identity.creatureId,out _);learner?.RemoveState(victim.identity.creatureId);}GameObject root=victim.identity!=null&&victim.identity.transform.parent!=null?victim.identity.transform.parent.gameObject:victim.identity?.gameObject;if(root!=null){root.SetActive(false);Destroy(root);}agents.Remove(victim);}
    private void RecordDeathPenalty(NativeAgent a){if(a==null||a.brain==null||a.deathRecorded)return;float penalty=a.brain.DeathReason=="predator"&&PredatorKillsEnabled?100f:25f;a.deathPenalty+=penalty;a.m1EnergyFitness-=penalty;a.deathRecorded=true;a.sequenceActive=false;a.observation=null;a.sequence=null;}
    private void RecoverFromExtinction(){if(!PopulationDynamicsEnabled)return;foreach(NativeAgent a in agents){GameObject root=a.identity!=null&&a.identity.transform.parent!=null?a.identity.transform.parent.gameObject:a.identity?.gameObject;if(root!=null){root.SetActive(false);Destroy(root);}}agents.Clear();SeedPopulation();RebuildSpeciation();Status="Native ecosystem recovered from extinction";}
    private void Evolve(){if(!PopulationDynamicsEnabled||agents.Count<2)return;NativeAgent parent=SelectLivingParent();if(parent==null)return;NativeAgent victim=agents.Where(a=>a!=parent&&!a.protectedOffspring).OrderByDescending(a=>a.model.BodyFitness).FirstOrDefault();if(victim==null)return;ReplaceAgent(victim,parent,victim.reservedSlot);MaintainPopulationInvariant();RebuildSpeciation();SaveCheckpoint();}

    private static BodyGenomeDto CreateSeedBody(int index)
    {
        var body=new BodyGenomeDto{genome_id=Guid.NewGuid().ToString("N"),limbs=new List<LimbGeneDto>()};int species=Mathf.Abs(index)%InitialBodySpeciesCount;
        if(species==0){body.limbs.Add(NewLimb(1,0,1));body.limbs.Add(NewLimb(2,0,5));body.limbs.Add(NewLimb(3,0,7));body.limbs.Add(NewLimb(4,2,3));body.limbs.Add(NewLimb(5,3,3));body.limbs.Add(NewLimb(6,0,0));}
        else if(species==1){body.limbs.Add(NewLimb(1,0,0));body.limbs.Add(NewLimb(2,0,4));body.limbs.Add(NewLimb(3,0,6));body.limbs.Add(NewLimb(4,1,3));body.limbs.Add(NewLimb(5,2,2));body.limbs.Add(NewLimb(6,3,3));}
        else if(species==2){body.limbs.Add(NewLimb(1,0,5));body.limbs.Add(NewLimb(2,0,7));body.limbs.Add(NewLimb(3,1,2));body.limbs.Add(NewLimb(4,1,3));body.limbs.Add(NewLimb(5,2,2));body.limbs.Add(NewLimb(6,2,3));}
        else if(species==3){int[] slots={0,1,4,5,6,7};for(int i=0;i<slots.Length;i++)body.limbs.Add(NewLimb(i+1,0,slots[i]));}
        else if(species==4){body.limbs.Add(NewLimb(1,0,4));body.limbs.Add(NewLimb(2,1,3));body.limbs.Add(NewLimb(3,2,3));body.limbs.Add(NewLimb(4,0,6));body.limbs.Add(NewLimb(5,4,2));body.limbs.Add(NewLimb(6,5,2));}
        else{body.limbs.Add(NewLimb(1,0,1));body.limbs.Add(NewLimb(2,1,2));body.limbs.Add(NewLimb(3,2,2));body.limbs.Add(NewLimb(4,0,7));body.limbs.Add(NewLimb(5,4,3));body.limbs.Add(NewLimb(6,5,3));}body.Validate();return body;
    }
    private static LimbGeneDto NewLimb(int id,int parent,int slot)=>new LimbGeneDto{innovation_id=id,parent_innovation_id=parent,attachment_slot=slot};
    private void Spawn(BodyGenomeDto body,string speciesId,string m1Species,NativeBrainWeights weights,int slot,int bodyAge=0,RtNeatGoalGenome m1Genome=null,NativeCreatureSave brainSave=null,NativeM3LearningState m3State=null)
    {
        body.Validate();Vector2 position=NativeSpawnPosition(slot);GameObject root=new GameObject("NativeCreature_"+body.genome_id.Substring(0,8));root.transform.position=position;CreatureIdentity identity=root.AddComponent<CreatureIdentity>();identity.creatureId=Guid.NewGuid().ToString("N");identity.speciesId=speciesId;GameObject torsoObject=new GameObject("Torso");torsoObject.transform.SetParent(root.transform);torsoObject.transform.position=position;torsoObject.AddComponent<Rigidbody2D>();torsoObject.AddComponent<SpriteRenderer>();torsoObject.AddComponent<BoxCollider2D>();Torso torso=torsoObject.AddComponent<Torso>();torso.InitFromGenome(identity,body);identity.torso=torso;identity.bodyGenomeJson=JsonConvert.SerializeObject(body);PlaceConstructedBodyOnGround(root);int layer=CreatureLayerBase+Mathf.Abs(slot)%CreatureLayerCount;SetLayerRecursively(root,layer);for(int other=CreatureLayerBase;other<CreatureLayerBase+CreatureLayerCount;other++)if(other!=layer)Physics2D.IgnoreLayerCollision(layer,other,true);Limb[] limbs=torso.GetAllLimbs().Where(l=>l!=null).Take(NativeCreatureModel.MaxLimbs).ToArray();CreatureBrain brain=torsoObject.AddComponent<CreatureBrain>();brain.Init(torso,limbs.ToList());brain.DeathsEnabled=PopulationDynamicsEnabled;brain.SetNativeMetadata(speciesId,m1Species);NativeGoalVisualizer visual=torsoObject.AddComponent<NativeGoalVisualizer>();visual.Initialize(torso,brain,Color.HSVToRGB(Mathf.Repeat(slot*.173f,1f),.8f,1f));NativeEnergyBar energyBar=torsoObject.AddComponent<NativeEnergyBar>();energyBar.Initialize(torso);var model=new NativeCreatureModel(weights,2003+slot);if(brainSave!=null)model.Restore(brainSave);m1Genome=m1Genome??rtNeat.Seed();NativeM3LearningState m3=m3State?.Clone()??new NativeM3LearningState{dynamics=NativeDynamicsWeights.Create(7331+slot)};var agent=new NativeAgent{identity=identity,brain=brain,limbs=limbs,goalVisualizer=visual,energyBar=energyBar,body=body,bodySignature=body.genome_id,model=model,m3=m3,m1Genome=m1Genome,m1Phenotype=new RtNeatGoalPhenotype(m1Genome),motionWindowStartPosition=torso.Rigidbody.position,previousEnergy=torso.energy,bodyAgeGenerations=Mathf.Max(0,bodyAge),reservedSlot=Mathf.Abs(slot)%NativeSpawnSlots};agents.Add(agent);modelsById[identity.creatureId]=model;learner?.SetState(identity.creatureId,m3);CaptureResetPose(agent);if(!enableM1&&trainingLaneRoot!=null)StartCurriculumTrial(agent);
    }
    private static void PlaceConstructedBodyOnGround(GameObject root){Physics2D.SyncTransforms();Collider2D[] colliders=root.GetComponentsInChildren<Collider2D>();if(colliders.Length==0)return;float min=colliders.Min(c=>c.bounds.min.y);root.transform.position+=Vector3.up*(WorldLayout.GroundTop+.03f-min);Physics2D.SyncTransforms();}
    private static Vector2 NativeSpawnPosition(int slot)=>WorldLayout.CreatureSpawnPosition(Mathf.Abs(slot)%NativeSpawnSlots);
    private static void SetLayerRecursively(GameObject root,int layer){root.layer=layer;foreach(Transform child in root.transform)SetLayerRecursively(child.gameObject,layer);}
    private void MutateBody(BodyGenomeDto body){body.genome_id=Guid.NewGuid().ToString("N");List<LimbGeneDto> enabled=body.limbs.Where(l=>l.enabled).ToList();if(enabled.Count<NativeCreatureModel.MaxLimbs&&random.NextDouble()<.65){var sites=new List<Vector2Int>();AddFreeSites(body,0,BodyMorphologyRules.TorsoSlots,sites);foreach(LimbGeneDto parent in enabled)if(GeneDepth(body,parent.innovation_id)<NativeCreatureModel.MaxPathDepth)AddFreeSites(body,parent.innovation_id,BodyMorphologyRules.LimbSlots,sites);if(sites.Count>0){Vector2Int site=sites[random.Next(sites.Count)];body.limbs.Add(NewLimb(body.limbs.Count==0?1:body.limbs.Max(l=>l.innovation_id)+1,site.x,site.y));}}else if(enabled.Count>4&&random.NextDouble()<.35){LimbGeneDto removable=enabled.Where(l=>!body.limbs.Any(o=>o.enabled&&o.parent_innovation_id==l.innovation_id)).OrderBy(_=>random.Next()).FirstOrDefault();if(removable!=null)removable.enabled=false;}body.Validate();}
    private static void AddFreeSites(BodyGenomeDto body,int parent,IEnumerable<int> slots,List<Vector2Int> output){HashSet<int> used=body.limbs.Where(l=>l.enabled&&l.parent_innovation_id==parent).Select(l=>l.attachment_slot).ToHashSet();foreach(int slot in slots)if(!used.Contains(slot))output.Add(new Vector2Int(parent,slot));}
    private static int GeneDepth(BodyGenomeDto body,int id){int depth=0;while(id!=0){LimbGeneDto gene=body.limbs.FirstOrDefault(l=>l.enabled&&l.innovation_id==id);if(gene==null)return NativeCreatureModel.MaxPathDepth;id=gene.parent_innovation_id;depth++;}return depth;}
    private void RebuildSpeciation(){List<NativeCreatureControllerView> views=agents.Where(a=>a.identity!=null&&a.brain!=null).Select(a=>new NativeCreatureControllerView(a.identity.creatureId,a.identity.speciesId,a.brain.M1SpeciesId,a.body,a.model.Weights,a.model.BodyFitness)).ToList();species=NativeNestedSpeciation.Rebuild(views,species);Dictionary<string,NativeAgent> byId=agents.Where(a=>a.identity!=null).ToDictionary(a=>a.identity.creatureId);foreach(NativeBodySpecies body in species)foreach(NativeBrainSubSpecies sub in body.subSpecies)foreach(NativeCreatureControllerView member in sub.members)if(byId.TryGetValue(member.id,out NativeAgent a))a.identity.speciesId=body.id;NativeRtNeatGoalPolicy.Speciate(agents.Where(a=>a.m1Genome!=null).Select(a=>a.m1Genome).ToList());foreach(NativeAgent a in agents)if(a.brain!=null&&a.m1Genome!=null)a.brain.SetNativeMetadata(a.identity.speciesId,"rtneat_"+a.m1Genome.species);}

    public void SaveCheckpoint()
    {
        if(saveTask!=null&&!saveTask.IsCompleted)return;if(random==null)random=new System.Random(1337^Generation^controlStep);var checkpoint=new NativeEcosystemCheckpoint{tick=Tick,generation=Generation,controlStep=controlStep,specialistSelectionCursor=specialistSelectionCursor,sharedM3Samples=SharedM3Samples,freshSequenceSamples=FreshSequenceSamples,sharedM3OptimizerSteps=SharedM3OptimizerSteps,goalSuccesses=GoalSuccesses,goalFailures=GoalFailures,experimentId=ExperimentId,randomState=random.Next(),nextEvolutionTicks=(long)(nextEvolution*1000f),rtNeat=rtNeat,sharedLearning=learner?.CaptureShared(),movementLearning=movementLearner?.Capture(),learnerQueueDrops=LearnerQueueDrops,capabilityValidated=agents.Count>0&&agents.All(a=>a.curriculum!=null&&a.curriculum.passedStages.Count>0)&&ControlFailures==0};foreach(NativeAgent a in agents)checkpoint.creatures.Add(new NativeCreatureCheckpoint{creatureId=a.identity.creatureId,speciesId=a.identity.speciesId,m1SpeciesId=a.brain.M1SpeciesId,bodyGenomeJson=JsonConvert.SerializeObject(a.body),brain=a.model.Capture(),m3=a.m3,m1Genome=a.m1Genome.Copy(),curriculum=a.curriculum?.Clone(),bodyFitness=float.IsInfinity(a.model.BodyFitness)?float.MaxValue:a.model.BodyFitness,deathPenalty=a.deathPenalty,m1EnergyFitness=a.m1EnergyFitness,previousEnergy=a.previousEnergy,deathRecorded=a.deathRecorded,bodyAgeGenerations=a.bodyAgeGenerations,protectedOffspring=a.protectedOffspring,temporaryGoalRewardBlock=a.temporaryGoalRewardBlock});string path=checkpointPath;CheckpointStatus="Snapshot queued";saveTask=Task.Run(()=>WriteCheckpointSnapshot(path,checkpoint));
    }
    private static BodyGenomeDto CreateMovementSchoolBody(){var body=new BodyGenomeDto{genome_id=Guid.NewGuid().ToString("N"),limbs=new List<LimbGeneDto>{NewLimb(1,0,5),NewLimb(2,1,3),NewLimb(3,0,7),NewLimb(4,3,2)}};body.Validate();return body;}
    private void TryLoad()
    {
        if(!File.Exists(checkpointPath)&&!File.Exists(checkpointPath+".bak")&&!File.Exists(checkpointPath+".stable"))return;Exception primary=null;foreach(string candidate in new[]{checkpointPath,checkpointPath+".bak",checkpointPath+".stable"}){if(!File.Exists(candidate))continue;try{LoadCheckpointCandidate(candidate);LoadedFromCheckpoint=true;CheckpointStatus=candidate==checkpointPath?"Loaded":candidate.EndsWith(".stable")?"Recovered validated capability":"Recovered backup";LastCheckpointSavedAt=CheckpointStatus;LastCheckpointError=primary?.Message??"";return;}catch(Exception e){if(primary==null)primary=e;else LastCheckpointError=(LastCheckpointError+" | "+e.Message).Trim();}}CheckpointStatus="Rejected; fresh population";if(string.IsNullOrEmpty(LastCheckpointError))LastCheckpointError=primary?.Message??"No compatible v22 checkpoint";
    }
    private static void WriteManifest(string path,NativeEcosystemCheckpoint checkpoint){string json=JsonConvert.SerializeObject(checkpoint,Formatting.None);using(var stream=new FileStream(path,FileMode.Create,FileAccess.Write,FileShare.None))using(var writer=new StreamWriter(stream)){writer.Write(json);writer.Flush();stream.Flush(true);}}
    private void WriteCheckpointSnapshot(string path,NativeEcosystemCheckpoint checkpoint){long started=System.Diagnostics.Stopwatch.GetTimestamp();try{Directory.CreateDirectory(Path.GetDirectoryName(path));checkpoint.tensorGeneration=DateTime.UtcNow.Ticks.ToString("x16");checkpoint.tensorFile="native_ecosystem_v26."+checkpoint.tensorGeneration+".bin";string tensorPath=Path.Combine(Path.GetDirectoryName(path),checkpoint.tensorFile),tensorTemp=tensorPath+".tmp",manifestTemp=path+".tmp",backup=path+".bak";NativeTensorCheckpointStore.Write(tensorTemp,checkpoint);checkpoint.tensorSha256=NativeTensorCheckpointStore.Sha256(tensorTemp);File.Move(tensorTemp,tensorPath);WriteManifest(manifestTemp,checkpoint);var check=JsonConvert.DeserializeObject<NativeEcosystemCheckpoint>(File.ReadAllText(manifestTemp));if(check==null||check.schema!=26||!NativeEcosystemCheckpoint.IsCompatibleConfiguration(check.configuration)||check.tensorSha256!=NativeTensorCheckpointStore.Sha256(tensorPath))throw new InvalidDataException("Temporary v26 checkpoint failed validation");if(File.Exists(path))File.Replace(manifestTemp,path,backup,true);else File.Move(manifestTemp,path);if(checkpoint.capabilityValidated)File.Copy(path,path+".stable",true);CleanupUnreferencedTensorGenerations(path);CheckpointStatus=checkpoint.capabilityValidated?"Saved + validated fallback":"Saved";LastCheckpointError="";LastCheckpointSavedAt=DateTime.Now.ToString("HH:mm:ss");}catch(Exception e){CheckpointStatus="Save failed";LastCheckpointError=e.Message;}finally{CheckpointMilliseconds=(float)((System.Diagnostics.Stopwatch.GetTimestamp()-started)*1000d/System.Diagnostics.Stopwatch.Frequency);}}
    private void LoadCheckpointCandidate(string manifestPath){var c=JsonConvert.DeserializeObject<NativeEcosystemCheckpoint>(File.ReadAllText(manifestPath));if(c==null||c.schema!=26||!NativeEcosystemCheckpoint.IsCompatibleConfiguration(c.configuration))throw new InvalidDataException("Native checkpoint schema/configuration mismatch");NativeTensorCheckpointStore.ValidateFileName(c.tensorFile);string tensorPath=Path.Combine(Path.GetDirectoryName(checkpointPath),c.tensorFile);if(!File.Exists(tensorPath)||NativeTensorCheckpointStore.Sha256(tensorPath)!=c.tensorSha256)throw new InvalidDataException("Native checkpoint tensor checksum mismatch");NativeTensorCheckpointStore.Read(tensorPath,c);learner?.RestoreShared(c.sharedLearning);movementLearner?.Restore(c.movementLearning);schoolBodiesExpanded=c.movementLearning?.simpleBodyQualified??false;rtNeat=c.rtNeat??new NativeRtNeatGoalPolicy();learnerQueueDrops=c.learnerQueueDrops;GoalSuccesses=c.goalSuccesses;GoalFailures=c.goalFailures;SharedM3Samples=c.sharedM3Samples;FreshSequenceSamples=c.freshSequenceSamples;SharedM3OptimizerSteps=c.sharedM3OptimizerSteps;ExperimentId=string.IsNullOrWhiteSpace(c.experimentId)?ExperimentId:c.experimentId;Tick=c.tick;Generation=c.generation;controlStep=c.controlStep;specialistSelectionCursor=c.specialistSelectionCursor;random=new System.Random(unchecked((int)c.randomState));foreach(NativeCreatureCheckpoint saved in c.creatures.Take(Mathf.Clamp(populationTarget,1,NativeSpawnSlots))){BodyGenomeDto body=JsonConvert.DeserializeObject<BodyGenomeDto>(saved.bodyGenomeJson);Spawn(body,saved.speciesId,saved.m1SpeciesId,saved.brain?.weights??seedPolicy.Clone(),agents.Count,saved.bodyAgeGenerations,saved.m1Genome??rtNeat.Seed(),saved.brain,saved.m3);NativeAgent a=agents[agents.Count-1];a.curriculum=saved.curriculum??new NativeCurriculumState();a.curriculum.passedStages=a.curriculum.passedStages??new List<int>();string generated=a.identity.creatureId;modelsById.TryRemove(generated,out _);learner.RemoveState(generated);a.identity.creatureId=saved.creatureId;modelsById[a.identity.creatureId]=a.model;a.deathPenalty=saved.deathPenalty;a.m1EnergyFitness=saved.m1EnergyFitness;a.previousEnergy=saved.previousEnergy;a.deathRecorded=saved.deathRecorded;a.protectedOffspring=saved.protectedOffspring;a.temporaryGoalRewardBlock=saved.temporaryGoalRewardBlock;if(!a.curriculum.Complete)StartCurriculumTrial(a);}}
    private static void CleanupUnreferencedTensorGenerations(string manifestPath){string directory=Path.GetDirectoryName(manifestPath);var keep=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(string manifest in new[]{manifestPath,manifestPath+".bak",manifestPath+".stable"})try{if(!File.Exists(manifest))continue;var c=JsonConvert.DeserializeObject<NativeEcosystemCheckpoint>(File.ReadAllText(manifest));if(c!=null&&!string.IsNullOrWhiteSpace(c.tensorFile))keep.Add(c.tensorFile);}catch{}foreach(string file in Directory.GetFiles(directory,"native_ecosystem_v26.*.bin")){string name=Path.GetFileName(file);if(!keep.Contains(name))try{File.Delete(file);}catch{}}}
    private void OnApplicationQuit()=>SaveCheckpoint(); private void OnDestroy(){if(Application.isPlaying){SaveCheckpoint();try{saveTask?.Wait(5000);}catch{}}movementLearner?.Dispose();learner?.Dispose();}
}
public enum NativeGoalMovement{Still,Toward,Away}
public sealed class NativeGoalVisualizer:MonoBehaviour
